INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(18001, 'Jeremiah 6:25', 'Jeremiah', 6, 25, '&nbsp;بهر مېدان ته مۀ ځئ، او په کوڅو کښې مۀ ګرځئ، ځکه چې زمونږ دشمن تُوره په لاس دے، او هرې خوا ته خوف خور شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18002, 'Jeremiah 6:26', 'Jeremiah', 6, 26, '&nbsp;مالِک خُدائ خپلو خلقو ته فرمائى، ”اے زما غوره شوى قومه، د ټاټ جامې واغوندئ او په ايرو کښې ولوغړېږئ. داسې بد بد وير وکړئ لکه څوک يې چې په يک يو زوئ باندې کوى،“ ځکه چې تباه کوونکى به په مونږ ناګهانه حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18003, 'Jeremiah 6:27', 'Jeremiah', 6, 27, '&nbsp;”اے يرمياه، ما تۀ د اوسپنې آزمائيونکے جوړ کړې او خپل قوم نه مې اوسپنه جوړه کړه. تۀ زما غوره شوے قوم وآزمايه ترڅو د دوئ د عمل درته پته ولګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18004, 'Jeremiah 6:28', 'Jeremiah', 6, 28, '&nbsp;هغوئ ټول سخت سرکشه شوى دى، او بدرد وائى او زړونه يې لکه د اوسپنې او پيتلو په شان سخت دى، او دوئ ټول بې‌ايمانى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18005, 'Jeremiah 6:29', 'Jeremiah', 6, 29, '&nbsp;د بټۍ لاندې خو سخت اور بليږى چې سيکه د سپينو زرو نه جدا کړى خو هغې زما قوم پاک نۀ کړو او بدعمله خلق ترې جدا نۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18006, 'Jeremiah 6:30', 'Jeremiah', 6, 30, '&nbsp;هغوئ ته رد شوى سپين زر وئيلے شى، ځکه ما، مالِک خُدائ هغوئ رد کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18007, 'Jeremiah 7:1', 'Jeremiah', 7, 1, '&nbsp;‏ مالِک خُدائ يرمياه له پېغام ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18008, 'Jeremiah 7:2', 'Jeremiah', 7, 2, '&nbsp;”د مالِک خُدائ د کور د دروازې سره ودرېږه او خلقو ته اعلان وکړه چې، اے د يهوداه ټولو اوسېدونکو او هغه کسانو چې په دې لارو د مالِک خُدائ کور ته د عبادت دپاره دننه کيږى، د مالِک خُدائ کلام واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18009, 'Jeremiah 7:3', 'Jeremiah', 7, 3, '&nbsp;مالِک خُدائ ربُ الافواج چې د بنى اِسرائيلو خُدائ پاک دے فرمائى چې د خپل چال چلن او سلوک اصلاح وکړئ، نو بيا به زۀ تاسو ته په دې زمکه د اوسېدو دپاره موقع درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18010, 'Jeremiah 7:4', 'Jeremiah', 7, 4, '&nbsp;د هغوئ په دروغژنو خبرو مۀ دوکه کېږئ چې وائى، ”مونږ دلته په امن کښې يُو ځکه چې دا د خُدائ پاک کور، د خُدائ پاک کور، د خُدائ پاک کور دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18011, 'Jeremiah 7:5', 'Jeremiah', 7, 5, '&nbsp;کۀ چرې په رښتيا سره تاسو خپل چال چلن او د ژوند طريقې بدلې کړئ، او په اِنصاف سره د يو بل سره معامله وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18012, 'Jeremiah 7:6', 'Jeremiah', 7, 6, '&nbsp;او چې نه تاسو په مسافر، يتيم او کونډه باندې ظلم وکړئ، او په دې ځائ کښې د بې‌ګناه وينه تويه نۀ کړئ، او د پردو معبودانو عبادت نه لاس په سر شئ او په دې خپل ځان ته نقصان مۀ رسوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18013, 'Jeremiah 7:7', 'Jeremiah', 7, 7, '&nbsp;نو بيا به زۀ تاسو په هم دې مُلک کښې د اوسېدو دپاره پرېږدم کوم چې ما ستاسو پلار نيکۀ له د تل دپاره په ميراث کښې ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18014, 'Jeremiah 7:8', 'Jeremiah', 7, 8, '&nbsp;خو ګورئ تاسو په دروغژنو خبرو باندې يقين ساتئ کومې چې بې‌فائدې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18015, 'Jeremiah 7:9', 'Jeremiah', 7, 9, '&nbsp;تاسو غلا، قتل او زنا کوئ او د دروغو قسمونه خورئ، او د بعل بُت ته د خوشبويۍ نذرانې پېش کوئ، او د هغه غېرو معبودانو عبادت کوئ چې تاسو د مخکښې نه نۀ دى پېژندلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18016, 'Jeremiah 7:10', 'Jeremiah', 7, 10, '&nbsp;او د دې نه وروستو هغه کور ته هم راځئ کوم چې زما په نامه ياديږى او زما په حضور کښې ودرېږئ او وايئ چې، ”مونږ په حفاظت کښې يُو،“ خو دوباره بيا خپلو ټولو حرامو کارونو پسې ګرځئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18017, 'Jeremiah 7:11', 'Jeremiah', 7, 11, '&nbsp;مالِک خُدائ فرمائى چې، ولې په کوم کور چې زما نامه ليکلے شوې ده د دې نه د ډاکوانو د پټېدو ځائ جوړ شوے دے څۀ؟ خبردار. څۀ چې تاسو کوئ زۀ دا هر څۀ ګورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18018, 'Jeremiah 7:12', 'Jeremiah', 7, 12, '&nbsp;تاسو د سيلا ښار ته لاړ شئ، په کوم ځائ کښې چې ما خپله وړومبۍ عبادتخانه جوړه کړې وه، نو هلته به درته دا پته ولګى چې ما خپل قوم بنى اِسرائيل سره د دوئ د شرارت په وجه هغه ښار سره څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18019, 'Jeremiah 7:13', 'Jeremiah', 7, 13, '&nbsp;مالِک خُدائ فرمائى چې، هرکله چې تاسو دا د شرارت کارونه کول، ما تاسو ته بار بار د دوئ په حقله وينا وکړه، خو تاسو زما وينا ته غوږ ونۀ نيولو. ما تاسو ته آواز درکړو خو تاسو جواب رانۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18020, 'Jeremiah 7:14', 'Jeremiah', 7, 14, '&nbsp;نو بيا چې ما کوم افت په سيلا ښار نازل کړے دے نو زۀ به هم هغه افت په دې عبادتخانې چې زما نوم پرې ليکلے شوے دے، او په دې عبادتخانه چې تاسو پرې يقين کوئ، او په دې ځائ چې ما ستاسو پلار نيکۀ او تاسو له درکړے دے نازل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18021, 'Jeremiah 7:15', 'Jeremiah', 7, 15, '&nbsp;زۀ به تاسو د خپل حضور نه داسې وشړم لکه څنګه چې ما ستاسو خپلوان د اِفرائيم خلق شړلى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18022, 'Jeremiah 7:16', 'Jeremiah', 7, 16, '&nbsp;مالِک خُدائ وفرمائيل، ”اے يرمياه، دې قوم ته نوره دُعا مۀ کوه. او د هغوئ دپاره ما ته سوال او فرياد مۀ کوه، ما ته د هغوئ سره د مدد کولو سفارش مۀ کوه، ځکه چې زۀ به ستا خبره نۀ اورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18023, 'Jeremiah 7:17', 'Jeremiah', 7, 17, '&nbsp;ولې تۀ هغه څۀ نۀ وينې چې کوم هغوئ د يهوداه په ښارونو کښې او د يروشلم په کوڅو کښې کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18024, 'Jeremiah 7:18', 'Jeremiah', 7, 18, '&nbsp;ماشومان خشاک راغونډوى، پلاران اور بلوى او ښځې اوړۀ اغږى او ترې نه پېړې جوړوى چې د آسمانې مَلِکې په نامه بُت ته ترې نازکې روټۍ پخې کړى. او هغوئ نورو معبودانو ته د څښلو نذرانې وړاندې کوى، او په خپل دې عمل ما غصه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18025, 'Jeremiah 7:19', 'Jeremiah', 7, 19, '&nbsp;آيا هغوئ په خپل دې عمل سره ما ته نقصان رسوى څۀ؟ خو هغوئ خپل ځان ته نقصان رسوى او په خپل دې عمل سره خپل ځانونه شرموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18026, 'Jeremiah 7:20', 'Jeremiah', 7, 20, '&nbsp;نو په دې وجه قادر مطلق خُدائ فرمائى، زما د قهر او غصې اور به د دې ځائ په انسانانو، ځناورو، او د مېدان په ونو او د زمکې په فصلونو نازل کړم. او هر څۀ به وسوزى او څوک به هم دا اور نۀ شى مړ کولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18027, 'Jeremiah 7:21', 'Jeremiah', 7, 21, '&nbsp;ربُ الافواج مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى، ”خپلې سوزېدونکې نذرانې او نورې قربانۍ واخلئ او په خپله يې غوښې وخورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18028, 'Jeremiah 7:22', 'Jeremiah', 7, 22, '&nbsp;ځکه کله چې ما ستاسو پلار نيکۀ د مِصر نه بهر راوويستل او هغوئ سره مې خبرې وکړې او خپل حُکمونه مې دوئ له ورکړل، نو ما هغوئ له د سوزېدونکو نذرانو او د قربانۍ په حقله حُکم نۀ وو ورکړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18029, 'Jeremiah 7:23', 'Jeremiah', 7, 23, '&nbsp;خو ما هغوئ له دا حُکم ورکړو، چې زما تابعدارى کوئ، نو زۀ به ستاسو خُدائ پاک يم او تاسو به زما خلق يئ. او د کومو لارو چې زۀ درته د تلو حکم کوم په هغې تلل کوئ. نو په دې کښې به ستا خير وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18030, 'Jeremiah 7:24', 'Jeremiah', 7, 24, '&nbsp;خو هغوئ زما دا حکم ونۀ منلو او زما کلام ته يې غوږ ونۀ نيولو، بلکې د خپل سرکشه زړۀ خواهشونه يې ومنل نو په دې باندې هغوئ د ښۀ کېدو په ځائ نور هم خراب شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18031, 'Jeremiah 7:25', 'Jeremiah', 7, 25, '&nbsp;د کومې ورځې نه چې ستاسو پلار نيکۀ د مِصر نه بهر راووتل تر اوسه پورې، ورځ په ورځ، وخت په وخت، ما خپل خِدمت کوونکى پېغمبران تاسو له درولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18032, 'Jeremiah 7:26', 'Jeremiah', 7, 26, '&nbsp;خو هغوئ زما خبرو ته غوږ ونۀ نيولو او نۀ يې توجو ورکړه. او هغوئ سرکشه وُو تر دې چې د خپل پلار نيکۀ نه يې هم زيات بدکارونه وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18033, 'Jeremiah 7:27', 'Jeremiah', 7, 27, '&nbsp;نو اے يرمياه، کله چې تۀ دوئ ته دا هر څۀ ووائې دوئ به تا ته غوږ ونۀ نيسى، او کله چې تۀ دوئ ته آواز ورکړې دوئ به تا له جواب نۀ درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18034, 'Jeremiah 7:28', 'Jeremiah', 7, 28, '&nbsp;نو دوئ ته ووايه، دا هغه قوم دے چې د مالِک خُدائ تابعدارى يې ونۀ کړله او اصلاح يې قبوله نۀ کړله. رښتينوالے د دوئ نه تلے دے، او هغه نور د دوئ د خُلو نه نۀ اورېدلے کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18035, 'Jeremiah 7:29', 'Jeremiah', 7, 29, '&nbsp;”خپل وېښتۀ د وير دپاره کل کړئ او لرې يې وغورزوئ. په اوچتو خُشکو غرونو د وير او ماتم سندرې ووايئ، ځکه چې مالِک خُدائ هغوئ رد کړل او دا نسل يې خپل قهر او غضب ته پرېښودلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18036, 'Jeremiah 7:30', 'Jeremiah', 7, 30, '&nbsp;مالِک خُدائ فرمائى چې د يهوداه خلقو زما د سترګو د وړاندې ګنده کارونه کړى دى، هغوئ زما په کور کښې خپل پليت بُتان اېښى دى په کومو چې زما نوم ليکلے دے او هغه يې ناپاکه کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18037, 'Jeremiah 7:31', 'Jeremiah', 7, 31, '&nbsp;او ورسره ورسره هغوئ د بنى‌هنوم په وادۍ کښې د توفت په نوم علاقائى عبادتخانې جوړې کړې چې هلته خپل زامن او لوڼه په اور کښې وسوزوى او قربانى يې کړى چې نۀ ورته ما حکم کړے وو او نۀ مې په خيال خاطر کښې تېر شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18038, 'Jeremiah 7:32', 'Jeremiah', 7, 32, '&nbsp;خو خبردار، يو وخت داسې راروان دے چې دې ځائ ته به نور د توفت يا د بنى‌هنوم وادى نۀ وائى بلکې خلق به ورته د قتل و غارت وادى وائى. ځکه چې هلته به دومره ډېر لاشونه ښخ کړے شى چې نور به د ښخولو دپاره ځائ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18039, 'Jeremiah 7:33', 'Jeremiah', 7, 33, '&nbsp;نو د هغوئ لاشونه به د هوا مارغانو او د ځنګلى ځناورو خوراک شى او داسې څوک به ژوندى نۀ وى چې دا ترې نه وشړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18040, 'Jeremiah 7:34', 'Jeremiah', 7, 34, '&nbsp;زۀ به د يهوداه په ښارونو او د يروشلم په کوڅو کښې د خندا خوشحالۍ آوازونه ختم کړم. د ناوې او زلمى آوازونه به نور په دې ښارونو کښې نۀ اورېدلے کيږى. ځکه چې دا مُلک به وران ويجاړ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18041, 'Jeremiah 8:1', 'Jeremiah', 8, 1, '&nbsp;مالِک خُدائ فرمائى چې، ”په هغه وخت کښې به دشمن د بادشاهانو او د يهوداه د آفسرانو، د اِمامانو او د پېغمبرانو او د يروشلم د نورو خلقو هډُوکى د قبرونو نه بهر راوباسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18042, 'Jeremiah 8:2', 'Jeremiah', 8, 2, '&nbsp;او د زمکې په مخ به يې خوارۀ وارۀ کړى او هلته به د هغه چا په وړاندې يعنې د نمر، سپوږمۍ او ستورو مخې ته پراتۀ وى د چا چې هغوئ عبادت کولو، ځکه چې هغوئ د دې څيزونو خِدمت کولو، او دې پسې روان وُو، او دې ته يې سجده کوله. د هغوئ هډُوکى به دوباره په خپلو کښې رايوځائ نۀ شى او نۀ به ښخ کړے شى بلکې د ډيران په شان به پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18043, 'Jeremiah 8:3', 'Jeremiah', 8, 3, '&nbsp;او هر چرته چې د دې بدعمله قوم ژوندى کسان کوم چې ما خوارۀ وارۀ کړى دى اوسيږى، نو هغوئ به د ژوند نه په مرګ باندې خوشحاله وى.“ مالِک خُدائ ربُ الافواج خُدائ دا وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18044, 'Jeremiah 8:4', 'Jeremiah', 8, 4, '&nbsp;”هغوئ ته ووايه چې مالِک خُدائ داسې فرمائى، هرکله چې څوک راپرېوځى، نو هغوئ بيا نۀ راپاڅى څۀ؟ هرکله چې يو سړے په غلطه لار روان شى آيا هغه به بيا راواپس نۀ شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18045, 'Jeremiah 8:5', 'Jeremiah', 8, 5, '&nbsp;نو بيا د يروشلم خلق د صحيح لارې نه ولې اوړېدلى دى؟ دوئ په دروغو او دوکه مارۍ کښې خپل ځان انغښتے دے او ما ته د واپس راتلو نه اِنکار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18046, 'Jeremiah 8:6', 'Jeremiah', 8, 6, '&nbsp;ما هغوئ ته په غور سره غوږ ونيولو خو هغوئ حقيقت نۀ وئيلو. او څوک هم په خپلو بدو کارونو باندې توبه ګار نۀ وُو او چا هم دا نۀ وئيل چې، ”دا مې کوم غلط کار وکړو؟“ لکه څنګه چې آس د جنګ مېدان ته په منډه روان وى دغه شان دوئ هم هر يو په خپلو غلطو لارو په تېزۍ سره روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18047, 'Jeremiah 8:7', 'Jeremiah', 8, 7, '&nbsp;تر دې چې مختلف مارغان لکه ډينګان، ګوګوشتکې، طوطاګرکى او زاڼى هم په دې پوهيږى چې اوس موسم بدل شو او راواپس کيږى. خو زما غوره شوے قوم زما د قانون نه ناخبره دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18048, 'Jeremiah 8:8', 'Jeremiah', 8, 8, '&nbsp;تاسو څنګه دا وايئ چې، مونږ ټول هوښياران يُو ځکه چې مونږ سره د مالِک خُدائ شريعت موجود دے؟ او حال دا چې د شريعت عالمانو په خپلو دروغو سره اصلى شريعت بدل کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18049, 'Jeremiah 8:9', 'Jeremiah', 8, 9, '&nbsp;ګورئ دغه هوښياران به وشرميږى او په خپل کم عقلتوب کښې به راګېر شى. ځکه چې هغوئ د مالِک خُدائ کلام رد کړو نو بيا د دوئ هوښيارتيا چرته لاړه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18050, 'Jeremiah 8:10', 'Jeremiah', 8, 10, '&nbsp;نو په دې وجه به زۀ د هغوئ ښځې پردو سړو ته حواله کړم او زمکه او جائيداد به يې هم نورو خلقو له ورکړم. ځکه چې د ماشومانو نه واخله تر بوډاګانو پورې هر يو د ناجائزه ګټې په لالچ کښې دى، د ‎پېغمبر نه واخله تر اِمام پورې ټول دوکه ماران دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18051, 'Jeremiah 8:11', 'Jeremiah', 8, 11, '&nbsp;هغوئ زما د خلقو د سختو زخمونو عرضى علاج کوى. او کله چې خير نۀ وى نو هغوئ وائى چې، خير دے، خير به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18052, 'Jeremiah 8:12', 'Jeremiah', 8, 12, '&nbsp;آيا هغوئ په خپل دې پليت عمل شرمېدل څۀ؟ نه، هغوئ بلکل شرم نۀ لرلو، هغوئ په دې هم نۀ پوهيږى چې شرم څۀ ته وائى. دوئ به د تباه شوو په مينځ کښې حساب شى. زۀ به دوئ هم ختم کړم کله چې زۀ هغوئ له سزا ورکوم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18053, 'Jeremiah 8:13', 'Jeremiah', 8, 13, '&nbsp;”زۀ به د دوئ پوره فصل تباه کړم. د انګورو په بوټى کښې به يوه دانه هم پاتې نۀ شى، او نۀ به اينځر د اينځر په ونه کښې وليدلے شى، د دوئ پاڼې به اوچې شى. او هر څۀ چې ما دوئ له ورکړى دى هغه به ترې نه واپس واخلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18054, 'Jeremiah 8:14', 'Jeremiah', 8, 14, '&nbsp;نو بيا به دوئ وائى چې مونږ ولې دلته په آرام سره ناست يُو؟ راځئ چې قلعه بند ښارونو ته وتښتو چې هلته کښې مړۀ شُو، ځکه چې مالِک خُدائ زمونږ خُدائ دا تباهى راباندې راوستې ده او د زهرو ډک جام يې مونږ ته څښلو دپاره راکړے دے. ځکه چې مونږ د مالِک خُدائ خلاف ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18055, 'Jeremiah 8:15', 'Jeremiah', 8, 15, '&nbsp;مونږ د امن په طمع وُو، خو مونږ هيڅ خير ونۀ ليدلو. مونږ د شفا حاصلولو اُميد کولو، بلکې د هغې په ځائ په مونږ يره راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18056, 'Jeremiah 8:16', 'Jeremiah', 8, 16, '&nbsp;واورئ. زمونږ د دشمن د آسونو شڼېدل د دان د ښار نه اورېدلے کيږى. او د هغوئ د آسونو د هڼېدلو نه ټوله زمکه په لړزېدو ده. هغوئ د دې دپاره راغلى دى چې دا مُلک او هر څۀ چې په کښې دى تباه کړى، ښارونه او هر څوک چې په کښې اوسيږى تېر کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18057, 'Jeremiah 8:17', 'Jeremiah', 8, 17, '&nbsp;مالِک خُدائ فرمائى، ”زۀ به ستاسو خلاف زهريله ماران درولېږم چې هيڅ قسم منتر به په هغې اثر نۀ کوى او هغه به تاسو وچيچى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18058, 'Jeremiah 8:18', 'Jeremiah', 8, 18, '&nbsp;نو بيا ما ووئيل چې خوشحالى زما نه لاړه او زما د خفګان علاج نشته، او دننه زړۀ مې بې‌هوشه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18059, 'Jeremiah 8:19', 'Jeremiah', 8, 19, '&nbsp;زما د خلقو ژړا ته غوږ ونيسئ چې په ټول مُلک کښې اورېدلے کيږى، هغوئ تپوس کوى وائى چې، ”آيا مالِک خُدائ صيون پرېښودے دے څۀ؟ آيا د هغوئ بادشاه نور دلته کښې نشته څۀ؟“ مالِک خُدائ ورته په جواب کښې فرمائى چې، ”تاسو ولې د هسې فضول او پردو بُتانو په عبادت زما قهر او غضب راوپارولو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18060, 'Jeremiah 8:20', 'Jeremiah', 8, 20, '&nbsp;خلق چغې سورې وهى او ژاړى چې، ”اوړے تېر شو، فصل لو شو، خو مونږ لا بچ نۀ يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18061, 'Jeremiah 8:21', 'Jeremiah', 8, 21, '&nbsp;زۀ د خپلو خلقو د دردونو سره دردمند شوم. او په پرېشانۍ کښې راګېر شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18062, 'Jeremiah 8:22', 'Jeremiah', 8, 22, '&nbsp;آيا په جِلعاد کښې مرهم نشته؟ آيا هلته طبيبان نشته څۀ؟ نو بيا ولې زما د قوم د زخمونو دپاره شفا نشته څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18063, 'Jeremiah 9:1', 'Jeremiah', 9, 1, '&nbsp;”کاش چې زما سر د اوبو چينه وے، او زما سترګې د اوښکو چينې وے، ترڅو چې ما شپه او ورځ د خپلو خلقو په قتلولو ژړا انګولا کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18064, 'Jeremiah 9:2', 'Jeremiah', 9, 2, '&nbsp;کاش چې په صحرا کښې زما يو سرائى وے، چرته چې ما خپل خلق پرېښودى وے او هلته د دوئ نه لرې اوسېدلم. ځکه چې دوئ ټول د خُدائ پاک سره بې‌وفائى کوى، او د بې‌ايمانانو يوه ډله ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18065, 'Jeremiah 9:3', 'Jeremiah', 9, 3, '&nbsp;مالِک خُدائ فرمائى، ”هغوئ د خپلو ژبو نه ليندې جوړې کړې دى او د دروغو غشى هر وخت ورَوى. د دې مُلک په ديانتدارۍ کښې صداقت نشته، هغوئ د يوې ګناه دپاسه بله ګناه کوى، هغوئ ما نۀ پېژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18066, 'Jeremiah 9:4', 'Jeremiah', 9, 4, '&nbsp;تاسو هر يو په خپل دوست نظر ساتئ او په خپل ورور هم اعتبار مۀ کوئ. ځکه چې هر يو ورور ستاسو دوکه مار دے، او هر يو دوست غېبت کوونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18067, 'Jeremiah 9:5', 'Jeremiah', 9, 5, '&nbsp;هر يو دوست بل دوست سره دوکه کوى، او يو هم رښتيا خبره نۀ کوى، هغوئ خپلو ژبو ته د دروغو وئيلو تعليم ورکړے دے، او په ګناه کولو سره خپل ځان ستړے کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18068, 'Jeremiah 9:6', 'Jeremiah', 9, 6, '&nbsp;مالِک خُدائ فرمائى چې، ”تاسو د دوکه مارانو او د دروغژنو په مينځ کښې اوسېږئ، او د خپلو دوکه کولو په وجه دوئ نۀ غواړى چې ما وپېژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18069, 'Jeremiah 9:7', 'Jeremiah', 9, 7, '&nbsp;نو په دې وجه مالِک خُدائ ربُ الافواج فرمائى، ”زۀ به دوئ لکه د کچه سپينو زرو په شان د اور بټۍ کښې واچوم، صفا به يې کړم او وبه يې آزمايمه، زۀ نور د دې ګناه ګار قوم سره څۀ وکړم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18070, 'Jeremiah 9:8', 'Jeremiah', 9, 8, '&nbsp;د هغوئ ژبې لکه د زهريله غشو په شان دى، او هغوئ همېشه دروغ وائى. او هغوئ په خولۀ د خپل ګاونډى سره خوږه لهجه کوى، خو په حقيقت کښې د هغوئ دپاره بدې منصوبې جوړوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18071, 'Jeremiah 9:9', 'Jeremiah', 9, 9, '&nbsp;مالِک خُدائ فرمائى چې، ”آيا زۀ دوئ ته د دې بدو کارونو سزا ورنۀ کړم څۀ؟ آيا د داسې قوم نه بدله خپله وانۀ خلم څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18072, 'Jeremiah 9:10', 'Jeremiah', 9, 10, '&nbsp;زۀ به د غرونو دپاره ژړا وکړم، او د بيابان د څرن په ځايونو به د غم سندرې ووايم. ځکه چې څوک هم په هغې تګ راتګ نۀ کوى، او ټول شينکے سوزېدلے او اوچ شوے دے او د رمو آوازونه په کښې نۀ اورېدلے کيږى. د هوا مارغان او ځنګلى ځناور ټول ترې نه تښتېدلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18073, 'Jeremiah 9:11', 'Jeremiah', 9, 11, '&nbsp;مالِک خُدائ فرمائى چې، ”زۀ به د يروشلم نه د خاورو ډېرے، او د ګيدړانو غار جوړ کړم. او د يهوداه ښارونه به وران او خاموشه کړم، نو هيڅوک به هلته کښې نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18074, 'Jeremiah 9:12', 'Jeremiah', 9, 12, '&nbsp;نو بيا به څوک دومره هوښيار وى چې په دې ټوله موضوع پوهه شى؟ چا ته د مالِک خُدائ نه دومره هدايت مِلاو شوے دے چې دا بيان کړى چې دا مُلک ولې وران شوے دے؟ دا ولې په ريګستان بدل شوے دے، او دومره ولې وران او خراب شوے دے چې هيڅوک هم پرې تېرېدلے نۀ شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18075, 'Jeremiah 9:13', 'Jeremiah', 9, 13, '&nbsp;مالِک خُدائ وفرمائيل چې، ”دا ځکه چې هغوئ زما شريعت هېر کړو کوم تعليم چې ما هغوئ ته وړاندې کړے وو، نۀ هغوئ زما کلام ومنلو او نۀ يې د هغې پيروى وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18076, 'Jeremiah 9:14', 'Jeremiah', 9, 14, '&nbsp;بلکې د دې په ځائ هغوئ د خپل سرکشه زړونو پيروى وکړه، او هغوئ د بعل د بُت پيروى وکړه لکه څنګه چې د هغوئ پلار نيکۀ ورته د عبادت کولو تعليم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18077, 'Jeremiah 9:15', 'Jeremiah', 9, 15, '&nbsp;نو ځکه، مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې، ګورئ، زۀ به هغوئ ته د خوړلو دپاره ګنډير ورکړم او د څښلو دپاره به زهريله اوبۀ ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18078, 'Jeremiah 9:16', 'Jeremiah', 9, 16, '&nbsp;زۀ به هغوئ په داسې قومونو کښې خوارۀ وارۀ کړم چې نۀ به يې دوئ او نۀ به يې د دوئ پلار نيکۀ پېژنى، او زۀ به په دوئ جنګ راولم ترڅو چې يې هلاک کړى نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18079, 'Jeremiah 9:17', 'Jeremiah', 9, 17, '&nbsp;مالِک خُدائ ربُ الافواج دا فرمائى چې، ”هغه څۀ چې کېدونکى دى په هغې غور وکړئ. سندرې ويونکې او ماتم کوونکې ښځې راوغواړئ چې راشى، او هغه ښځې راوغواړئ چې په مړى په ژړا کولو کښې ماهرې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18080, 'Jeremiah 9:18', 'Jeremiah', 9, 18, '&nbsp;لاړ شئ او هغوئ زر راولئ چې په مونږ باندې دومره ژړا او سندرې ووائى ترڅو زمونږ سترګې د اوښکو نه ډکې شى، او زمونږ د بڼو نه اوښکې روانې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18081, 'Jeremiah 9:19', 'Jeremiah', 9, 19, '&nbsp;د صيون نه د ژړا آوازونه اورېدلے کيږى چې وائى، ”واى، واى، مونږه څنګه تباه شُو او په شرمونو وشرمېدو. مونږ مُلک پرېښودو ته مجبوره شوى يُو، ځکه چې زمونږ کورونه تباه شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18082, 'Jeremiah 9:20', 'Jeremiah', 9, 20, '&nbsp;اے ښځو، د مالِک خُدائ کلام ته غوږ ونيسئ، او د هغۀ د خولې هرې خبرې ته غوږ ونيسئ. خپلو لوڼو ته د سندرو او ماتم کولو تعليم ورکړئ، او يو بل ته په خپلو کښې د ماتم کولو تعليم ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18083, 'Jeremiah 9:21', 'Jeremiah', 9, 21, '&nbsp;ځکه چې مرګ زمونږ کور ته په کړکو راننوتے دے او زمونږ قلعو ته رادننه شوے دے، هغه اوس ماشومان د کوڅو نه او ځوانان د بازارونو او چوکونو نه راټولوى او تېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18084, 'Jeremiah 9:22', 'Jeremiah', 9, 22, '&nbsp;مالِک خُدائ فرمائى، ”خلقو ته ووايه چې د مړو لاشونه به په پټو کښې لکه د ډېران د سرې پراتۀ وى، او لکه د غنمو وږې په شان د لَوګرى شا ته اخوا ديخوا پراتۀ وى دغه شان به مړى هرې خوا ته پراتۀ وى او د راټولولو به يې څوک نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18085, 'Jeremiah 9:23', 'Jeremiah', 9, 23, '&nbsp;مالِک خُدائ فرمائى، ”هوښيار دې په خپله هوښيارتيا فخر ونۀ کړى، نۀ دې زورَور په خپل زور باندې او نۀ دې دولتمند په خپل دولت باندې فخر وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18086, 'Jeremiah 9:24', 'Jeremiah', 9, 24, '&nbsp;مالِک خُدائ فرمائى چې، ”کۀ څوک فخر کول غواړى نو هغه دې په دې خبره فخر وکړى چې دوئ ما پېژنى او په دې پوهيږى چې زۀ هغه مالِک خُدائ يم چې په زمکه باندې نۀ ختمېدونکې مينه، عدل و اِنصاف او صداقت راولم. ځکه چې په دې څيزونو کښې زما خوشحالى ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18087, 'Jeremiah 9:25', 'Jeremiah', 9, 25, '&nbsp;مالِک خُدائ فرمائى، ”هغه ورځې راروانې دى چې، زۀ به ټولو هغه خلقو ته سزا ورکړم څوک چې صرف جسمانى سنت شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18088, 'Jeremiah 9:26', 'Jeremiah', 9, 26, '&nbsp;زۀ به مِصر، ادوم، عمون، موآب او هغوئ ته څوک چې په دشتو او ميرو کښې اوسيږى سزا ورکړم، او ورسره به بنى اِسرائيل ته هم سزا ورکړم. ځکه چې د ټولو بُت پرستو قومونو په شان، د دوئ زړونه هم مالِک خُدائ ته وقف نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18089, 'Jeremiah 10:1', 'Jeremiah', 10, 1, '&nbsp;اے بنى اِسرائيلو، د مالِک خُدائ پېغام ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18090, 'Jeremiah 10:2', 'Jeremiah', 10, 2, '&nbsp;مالِک خُدائ فرمائى چې، ”د نورو قومونو په طريقو تلل مۀ کوئ، او د هغوئ په شان په آسمان کښې د ستورو د ګردش او نښو نښانو نه مۀ يرېږئ تر دې چې هغوئ په خپله يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18091, 'Jeremiah 10:3', 'Jeremiah', 10, 3, '&nbsp;ځکه چې د نورو قومونو رِواج فضول دے، هغوئ د ځنګل نه ونه راووهى، او بيا کاريګر ترې نه په خپله په ترښځ بُت جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18092, 'Jeremiah 10:4', 'Jeremiah', 10, 4, '&nbsp;او وروستو هغه په سرو او سپينو زرو باندې ښائسته کړى او بيا دوئ په څټک او مېخ سره دا بُت په يو ځائ کښې ټک وهى چې راونۀ غورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18093, 'Jeremiah 10:5', 'Jeremiah', 10, 5, '&nbsp;د هغوئ بُتان داسې دى لکه د بادرنګو په پټى کښې چې ګوډاګے د مارغانو د شړلو دپاره ودرولے شوے وى، کوم چې نۀ خبرې کولے شى، او نۀ هغه په خپله ګرځېدے شى، په کار دے چې نور خلق دا اوچت کړى. د هغوئ نه مۀ يرېږه، دوئ تا ته ضرر نۀ شى در رسولے او نۀ څۀ فائده درکولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18094, 'Jeremiah 10:6', 'Jeremiah', 10, 6, '&nbsp;اے مالِکه خُدايه، ستا په شان بل هيڅ څوک هم نشته، تۀ لوئ يې، او تۀ زورَور يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18095, 'Jeremiah 10:7', 'Jeremiah', 10, 7, '&nbsp;اے د قومونو بادشاه، څوک به ستا نه نۀ يريږى؟ تۀ د ثناء او صِفت لائق يې. د دُنيا په ټولو هوښيارو خلقو او بادشاهتونو کښې بل څوک ستا په شان نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18096, 'Jeremiah 10:8', 'Jeremiah', 10, 8, '&nbsp;هغوئ ټول کم عقل او بې‌وقوفه دى، ځکه هغوئ چې د څۀ عبادت کوى هغه د لرګى نه جوړ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18097, 'Jeremiah 10:9', 'Jeremiah', 10, 9, '&nbsp;هغوئ د ترسيس نه د سپينو زرو تختې او د اوفاز نه سرۀ زر راوړى. کله چې زرګر ترې نه بُت جوړ کړى نو بيا درزيان ورته آسمانى او کاسنى کپړې تياروى او هغۀ ته يې وراغوندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18098, 'Jeremiah 10:10', 'Jeremiah', 10, 10, '&nbsp;بلکې مالِک خُدائ رښتونے خُدائ پاک دے. هغه ژوندے خُدائ پاک او ابدى بادشاه دے. د هغۀ د قهر و غضب نه ټوله دُنيا لړزيږى، قومونه د هغۀ غضب ته ټينګېدے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18099, 'Jeremiah 10:11', 'Jeremiah', 10, 11, '&nbsp;هغه خلقو ته څوک چې د نورو معبودانو عبادت کوى دا ووايه چې، ”هغه تش په نامه معبودانو چې زمکه او آسمانونه يې نۀ دى جوړ کړى، هغه به د زمکې د مخ نه او د آسمان د لاندې نه بلکل ختم شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18100, 'Jeremiah 10:12', 'Jeremiah', 10, 12, '&nbsp;خو مالِک خُدائ په خپل قدرت سره زمکه جوړه کړه. او په خپل حکمت سره يې دُنيا قائمه کړه. او په خپل عقل يې آسمانونه خوارۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');